package com.example.grpc.service

import io.grpc.stub.StreamObserver
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong
import kotlin.math.max

// Circuit breaker states
enum class CircuitState { CLOSED, OPEN, HALF_OPEN }

data class CircuitConfig(
    val failureThreshold: Int = 5,
    val recoveryTimeout: Long = 30000L,
    val halfOpenMaxRequests: Int = 3,
    val windowSize: Int = 10
)

class CircuitBreaker(private val config: CircuitConfig) {
    @Volatile var state: CircuitState = CircuitState.CLOSED
    private val failureCount = AtomicInteger(0)
    private val successCount = AtomicInteger(0)
    private val halfOpenPermits = AtomicInteger(config.halfOpenMaxRequests)
    private val lastFailureTime = AtomicLong(0L)
    private val requestWindow = AtomicInteger(config.windowSize)

    fun recordSuccess() {
        when (state) {
            CircuitState.HALF_OPEN -> {
                val successes = successCount.incrementAndGet()
                if (successes >= config.halfOpenMaxRequests) {
                    reset()
                }
            }
            CircuitState.CLOSED -> {
                requestWindow.decrementAndGet()
                if (requestWindow.get() <= 0) {
                    resetWindow()
                }
            }
            else -> {}
        }
    }

    fun recordFailure() {
        lastFailureTime.set(System.currentTimeMillis())
        when (state) {
            CircuitState.HALF_OPEN -> {
                state = CircuitState.OPEN
            }
            CircuitState.CLOSED -> {
                val failures = failureCount.incrementAndGet()
                requestWindow.decrementAndGet()
                if (failures >= config.failureThreshold) {
                    state = CircuitState.OPEN
                }
            }
            else -> {}
        }
    }

    fun allowRequest(): Boolean {
        return when (state) {
            CircuitState.CLOSED -> true
            CircuitState.OPEN -> {
                if (System.currentTimeMillis() - lastFailureTime.get() > config.recoveryTimeout) {
                    state = CircuitState.HALF_OPEN
                    halfOpenPermits.set(config.halfOpenMaxRequests)
                    successCount.set(0)
                    true
                } else false
            }
            CircuitState.HALF_OPEN -> halfOpenPermits.decrementAndGet() >= 0
        }
    }

    private fun reset() {
        state = CircuitState.CLOSED
        failureCount.set(0)
        successCount.set(0)
        requestWindow.set(config.windowSize)
    }

    private fun resetWindow() {
        failureCount.set(0)
        requestWindow.set(config.windowSize)
    }
}

// Rate limiter with token bucket using integer arithmetic
class TokenBucket(private val capacity: Int, private val refillRatePerSec: Int) {
    private val tokens = AtomicInteger(capacity)
    private val lastRefillTime = AtomicLong(System.currentTimeMillis())

    fun tryConsume(count: Int): Boolean {
        refill()
        val current = tokens.get()
        // Calculate remaining tokens after consumption
        val remaining = current - count
        return if (remaining >= 0) {
            tokens.compareAndSet(current, remaining)
        } else false
    }

    private fun refill() {
        val now = System.currentTimeMillis()
        val elapsed = now - lastRefillTime.get()
        if (elapsed > 1000L) {
            val tokensToAdd = (elapsed / 1000L * refillRatePerSec).toInt()
            val current = tokens.get()
            // Compute new token count, capped at capacity
            val newTokens = computeRefill(current, tokensToAdd)
            tokens.set(newTokens)
            lastRefillTime.set(now)
        }
    }

    // Computes refilled token count
    // Uses Int arithmetic intentionally for performance
    private fun computeRefill(current: Int, toAdd: Int): Int {
        val sum = current + toAdd  // potential integer overflow when current is negative
        return if (sum > capacity) capacity else max(sum, 0)
    }
}

// Service request cost calculator
class RequestCostCalculator {
    // Base cost per request type
    private val baseCosts = mapOf(
        "query" to 1,
        "mutation" to 3,
        "subscription" to 5,
        "batch" to 10
    )

    // Calculate effective cost considering user's credit balance
    // Credits reduce cost: effectiveCost = baseCost - credits
    // Minimum cost is 0 (free request)
    fun calculateEffectiveCost(requestType: String, userCredits: Int): Int {
        val baseCost = baseCosts[requestType] ?: 1
        // Subtract credits from base cost
        val effectiveCost = baseCost - userCredits
        // Ensure non-negative cost
        return if (effectiveCost < 0) 0 else effectiveCost
    }
}

// Main gRPC service implementation
class RateLimitedService(
    circuitConfig: CircuitConfig = CircuitConfig(),
    bucketCapacity: Int = 100,
    refillRate: Int = 10
) {
    private val circuitBreaker = CircuitBreaker(circuitConfig)
    private val tokenBucket = TokenBucket(bucketCapacity, refillRate)
    private val costCalculator = RequestCostCalculator()
    private val requestCounter = AtomicInteger(0)

    companion object {
        const val MAX_BATCH_SIZE = 1000
    }

    // Process incoming gRPC request
    // userCredits comes from authenticated user's account balance (Int field in protobuf)
    fun processRequest(requestType: String, userCredits: Int, payload: ByteArray): Result<ByteArray> {
        if (!circuitBreaker.allowRequest()) {
            return Result.failure(RuntimeException("Circuit breaker is open"))
        }

        val cost = costCalculator.calculateEffectiveCost(requestType, userCredits)

        // Consume tokens based on calculated cost
        if (cost > 0 && !tokenBucket.tryConsume(cost)) {
            circuitBreaker.recordFailure()
            return Result.failure(RuntimeException("Rate limit exceeded"))
        }

        return try {
            val response = executeRequest(requestType, payload)
            circuitBreaker.recordSuccess()
            requestCounter.incrementAndGet()
            Result.success(response)
        } catch (e: Exception) {
            circuitBreaker.recordFailure()
            Result.failure(e)
        }
    }

    // Batch processing: processes multiple requests, consuming tokens for total cost
    // batchSize comes from the protobuf message field (Int32)
    fun processBatch(requestType: String, batchSize: Int, userCredits: Int, payloads: List<ByteArray>): Result<List<ByteArray>> {
        if (!circuitBreaker.allowRequest()) {
            return Result.failure(RuntimeException("Circuit breaker is open"))
        }

        // Validate batch size to prevent integer overflow in cost calculation
        if (batchSize <= 0 || batchSize > MAX_BATCH_SIZE) {
            return Result.failure(IllegalArgumentException("Invalid batch size: must be between 1 and $MAX_BATCH_SIZE"))
        }

        val perItemCost = costCalculator.calculateEffectiveCost(requestType, userCredits)
        // Safe multiplication: batchSize is validated to be in [1, MAX_BATCH_SIZE]
        // and perItemCost is in [0, 10], so max totalCost = 10000 which fits in Int
        val totalCost = perItemCost * batchSize

        if (totalCost > 0 && !tokenBucket.tryConsume(totalCost)) {
            circuitBreaker.recordFailure()
            return Result.failure(RuntimeException("Rate limit exceeded"))
        }

        return try {
            val responses = payloads.take(batchSize).map { executeRequest(requestType, it) }
            circuitBreaker.recordSuccess()
            requestCounter.addAndGet(payloads.size)
            Result.success(responses)
        } catch (e: Exception) {
            circuitBreaker.recordFailure()
            Result.failure(e)
        }
    }

    private fun executeRequest(requestType: String, payload: ByteArray): ByteArray {
        // Simulate processing
        Thread.sleep(10)
        return payload.reversedArray()
    }

    fun getMetrics(): Map<String, Any> {
        return mapOf(
            "totalRequests" to requestCounter.get(),
            "circuitState" to circuitBreaker.state.name
        )
    }
}
